def as_list(value):
    return value if isinstance(value, list) else [value]


def grants_send(statement):
    actions = [str(a).lower() for a in as_list(statement.get("Action", []))]
    resources = as_list(statement.get("Resource", []))
    return (
        statement.get("Effect") == "Allow"
        and any(a in ("sqs:sendmessage", "sqs:*", "*") for a in actions)
        and any(r in (queue_arn, "*") for r in resources)
    )


def open_to_services_or_anyone(statement):
    principal = statement.get("Principal")
    if principal == "*":
        return True
    if isinstance(principal, dict):
        return "*" in as_list(principal.get("AWS", [])) or "sns.amazonaws.com" in as_list(principal.get("Service", []))
    return False


def limited_to_topic(statement):
    for operator, pairs in (statement.get("Condition") or {}).items():
        if operator.lower() in ("arnequals", "arnlike", "stringequals", "stringlike"):
            for key, values in pairs.items():
                if key.lower() == "aws:sourcearn" and as_list(values) == [topic_arn]:
                    return True
    return False


statements = as_list(json.loads(attrs["Policy"]).get("Statement", []))
grants = [s for s in statements if grants_send(s) and open_to_services_or_anyone(s)]
assert grants, "the policy does not let the topic send messages to the queue"
assert all(limited_to_topic(s) for s in grants), "the policy lets senders other than order-events send to the queue"

